input.content:
/* Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: #0a0a0a;
    overflow-x: hidden;
    height: 300vh; /* Extended scroll for the growth timeline */
    position: relative;
    overflow-y: auto;
    color: white;
}

#container {
    position: relative;
    width: 100vw;
    height: 100vh;
    overflow: visible;
    margin: 0 auto;
}

#plant-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 800px;
    height: 600px;
    pointer-events: none;
    z-index: 10;
}

.info-panel {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 40%;
    max-width: 400px;
    padding: 20px;
    pointer-events: all;
    z-index: 20;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.info-panel.active {
    opacity: 1;
}

#info-left {
    left: 5%;
    text-align: right;
}

#info-right {
    right: 5%;
    text-align: left;
}

.info-content {
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(10px);
    border-radius: 12px;
    padding: 24px;
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.info-header {
    display: flex;
    align-items: center;
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.category-number {
    font-family: 'Courier New', Courier, monospace;
    font-size: 14px;
    opacity: 0.7;
    margin-right: 12px;
    min-width: 24px;
    text-align: center;
}

.category-name {
    font-size: 18px;
    font-weight: 600;
    margin-bottom: 4px;
}

.process-name {
    font-size: 16px;
    font-weight: 500;
    color: #4fc3f7;
    margin-bottom: 12px;
}

.process-description {
    font-size: 14px;
    line-height: 1.5;
    opacity: 0.9;
    margin-bottom: 16px;
}

.io-section {
    display: flex;
    justify-content: space-between;
    font-size: 13px;
}

.io-label {
    opacity: 0.7;
}

.io-value {
    font-weight: 600;
    color: #ffffff;
}

/* Responsive adjustments will go in responsive.css */

