input.content:
/* Responsive Styles */
@media (max-width: 1400px) {
    #plant-container {
        width: 700px;
        height: 500px;
    }

    .info-panel {
        width: 35%;
        max-width: 350px;
    }
}

@media (max-width: 1024px) {
    #plant-container {
        width: 600px;
        height: 450px;
    }

    .info-panel {
        width: 40%;
        max-width: 300px;
    }

    .info-content {
        padding: 20px;
    }

    .category-name {
        font-size: 16px;
    }

    .process-name {
        font-size: 14px;
    }

    .process-description {
        font-size: 13px;
    }
}

@media (max-width: 768px) {
    body {
        height: 350vh; /* Increase scroll height for mobile */
    }

    #plant-container {
        width: 100vw;
        height: 80vh;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
    }

    .info-panel {
        position: static;
        width: 100%;
        max-width: 100%;
        transform: none;
        padding: 15px;
        margin:       margin: 10px 0;
    }

    #info-left,
    #info-right {
        left: 0;
        right: 0;
        text-align: center;
    }

    .info-content {
        margin: 0 auto;
    }

    .io-section {
        flex-direction: column;
        gap: 8px;
        text-align: center;
    }
}

@media (max-width: 480px) {
    body {
        height: 400vh;
    }

    .info-content {
        padding: 15px;
    }

    .category-name {
        font-size: 15px;
    }

    .process-name {
        font-size: 13px;
    }

    .process-description {
        font-size: 12px;
    }

    .io-label,
    .io-value {
        font-size: 12px;
    }
}

