input.content:
/* Animation Styles */
.soil {
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 200px;
    height: 100px;
    background: radial-gradient(ellipse at center, #3e2723 0%, #2e1b17 70%, #1b100e 100%);
    border-radius: 50% 50% 40% 40%;
    overflow: hidden;
    z-index: 5;
}

.seed {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 28px;
    background: radial-gradient(circle at 30% 30%, #8d6e63, #5d4037);
    border-radius: 50%;
    z-index: 10;
}

.seed-label {
    position: absolute;
    bottom: 60px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(0, 0, 0, 0.7);
    color: #fff;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 12px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.root {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    width: 4px;
    background: linear-gradient(to bottom, #8d6e63, #6d4c41);
    position: absolute;
    z-index: 8;
}

.stem {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    background: linear-gradient(to top, #6d4c41, #8d6e63);
    z-index: 9;
}

.branch {
    position: absolute;
    width: 3px;
    background: linear-gradient(to top, #8d6e63, #6d4c41);
    z-index: 7;
}

.leaf {
    position: absolute;
    width: 0;
    height: 0;
    border-left: 6px solid transparent;
    border-right: 6px solid transparent;
    border-bottom: 12px solid #4caf50;
    z-index: 6;
}

.flower-bud {
    position: absolute;
    width: 16px;
    height: 20px;
    background: #9c27b0;
    border-radius: 50% 50% 40% 40%;
    z-index: 5;
}

.petal {
    position: absolute;
    width: 0;
    height: 0;
    border-left: 8px solid transparent;
    border-right: 8px solid transparent;
    border-bottom: 16px solid #9c27b0;
    z-index: 4;
}

.fruit {
    position: absolute;
    width: 24px;
    height: 24px;
    background: #ff9800;
    border-radius: 50%;
    z-index: 3;
}

.data-particle {
    position: absolute;
    width: 2px;
    height: 2px;
    background: #4fc3f7;
    border-radius: 50%;
    pointer-events: none;
    z-index: 15;
}

.connector {
    position: absolute;
    stroke: #4fc3f7;
    stroke-width: 2;
    fill: none;
    opacity: 0;
    z-index: 12;
}

.connector-line {
    stroke-dasharray: 6;
    stroke-dashoffset: 0;
    animation: dash 2s linear infinite;
}

@keyframes dash {
    to {
        stroke-dashoffset: -12;
    }
}

.particle-pulse {
    position: absolute;
    width: 4px;
    height: 4px;
    background: #4fc3f7;
    border-radius: 50%;
    opacity: 0;
    pointer-events: none;
    z-index: 16;
}

/* Animation classes for different states */
.grow-root {
    transform-origin: bottom;
}

.grow-stem {
    transform-origin: bottom;
}

.grow-branch {
    transform-origin: bottom;
}

.unfold-leaf {
    transform-origin: bottom;
}

.open-petal {
    transform-origin: center;
}

.grow-fruit {
    transform-origin: center;
}

.pulse-data {
    animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
    0% {
        opacity: 0.3;
        transform: scale(0.8);
    }
    50% {
        opacity: 0.8;
        transform: scale(1.2);
    }
    100% {
        opacity: 0.3;
        transform: scale(0.8);
    }
}

.seed-fall {
    animation: fall 2s ease-out forwards;
}

@keyframes fall {
    0% {
        top: -50px;
        opacity: 0;
        transform: translateX(-50%) rotate(0deg);
    }
    70% {
        opacity: 1;
    }
    100% {
        top: 20px;
        opacity: 1;
        transform: translateX(-50%) rotate(10deg);
    }
}

.seed-impact {
    animation: impact 0.3s ease-out;
}

@keyframes impact {
    0% {
        transform: translateX(-50%) translateY(0) scale(1);
    }
    30% {
        transform: translateX(-50%) translateY(4px) scale(1.1);
    }
    100% {
        transform: translateX(-50%) translateY(0) scale(1);
    }
}

.seed-rotate {
    animation: rotate 3s ease-in-out infinite alternate;
}

@keyframes rotate {
    from {
        transform: translateX(-50%) rotate(0deg);
    }
    to {
        transform: translateX(-50%) rotate(5deg);
    }
}

.seed-swell {
    animation: swell 2s ease-in-out forwards;
}

@keyframes swell {
    0% {
        width: 20px;
        height: 28px;
    }
    50% {
        width: 24px;
        height: 32px;
    }
    100% {
        width: 26px;
        height: 34px;
    }
}

.seed-crack {
    animation: crack 1.5s ease-out forwards;
}

@keyframes crack {
    0% {
        background: radial-gradient(circle at 30% 30%, #8d6e63, #5d4037);
        border-radius: 50%;
    }
    30% {
        background: radial-gradient(circle at 30% 30%, #8d6e63, #5d4037);
        border-radius: 50%;
    }
    100% {
        background: radial-gradient(circle at 30% 30%, #8d6e63, #5d4037);
        border-radius: 50% 50% 40% 40%;
    }
}

