// Data-flow.js - Handles data movement, particle animations, and data flow visualization

export function initDataFlow() {
    const container = document.getElementById('plant-container');
    const particlesContainer = document.getElementById('particles-container');
    const soil = document.getElementById('soil');
    const seed = document.getElementById('seed');
    const rootsContainer = document.getElementById('roots-container');
    const stem = document.getElementById('stem');
    const branchesContainer = document.getElementById('branches-container');
    const leavesContainer = document.getElementById('leaves-container');
    const flowerContainer = document.getElementById('flower-container');

    // Data particles array to track active particles
    let dataParticles = [];

    // Create initial data particles in soil
    function createSoilDataParticles(count = 20) {
        for (let i = 0; i < count; i++) {
            createDataParticle({
                x: Math.random() * 200 - 50, // Random within soil area
                y: Math.random() * 100 + 200, // Within soil height
                type: 'soil',
                speed: Math.random() * 0.5 + 0.2
            });
        }
    }

    // Create a data particle
    function createDataParticle(options = {}) {
        const particle = document.createElement('div');
        particle.className = 'data-particle';
        particle.style.position = 'absolute';
        particle.style.width = '2px';
        particle.style.height = '2px';
        particle.style.background = getParticleColor(options.type || 'data');
        particle.style.borderRadius = '50%';
        particle.style.pointerEvents = 'none';
        particle.style.zIndex = '15';

        // Set initial position
        particle.style.left = `${options.x || 0}px`;
        particle.style.top = `${options.y || 0}px`;

        // Store particle data
        particle.dataset.type = options.type || 'data';
        particle.dataset.speed = options.speed || 0.5;
        particle.dataset.targetX = options.targetX || 0;
        particle.dataset.targetY = options.targetY || 0;
        particle.dataset.homeX = options.x || 0;
        particle.dataset.homeY = options.y || 0;

        particlesContainer.appendChild(particle);
        dataParticles.push(particle);

        return particle;
    }

    // Get particle color based on type
    function getParticleColor(type) {
        const colors = {
            soil: '#4fc3f7',
            root: '#ffb74d',
            stem: '#81c784',
            branch: '#fff176',
            leaf: '#a5d6a7',
            flower: '#ce93d8',
            data: '#4fc3f7',
            processing: '#ff8a65',
            intelligence: '#ba68c8',
            energy: '#e57373'
        };
        return colors[type] || '#ffffff';
    }

    // Animate data particles
    function animateDataParticles() {
        dataParticles.forEach(particle => {
            const type = particle.dataset.type;
            const speed = parseFloat(particle.dataset.speed);
            const targetX = parseFloat(particle.dataset.targetX) || 0;
            const targetY = parseFloat(particle.dataset.targetY) || 0;
            const homeX = parseFloat(particle.dataset.homeX) || 0;
            const homeY = parseFloat(particle.dataset.homeY) || 0;

            let currentX = parseFloat(particle.style.left) || 0;
            let currentY = parseFloat(particle.style.top) || 0;

            // Different behaviors based on type
            if (type === 'soil') {
                // Slow drift in soil
                const driftX = (Math.sin(Date.now() * 0.001 + particle.dataset.homeX) * 0.3);
                const driftY = (Math.cos(Date.now() * 0.001 + particle.dataset.homeY) * 0.2);
                particle.style.left = `${homeX + driftX}px`;
                particle.style.top = `${homeY + driftY}px`;
            } else if (type === 'root-to-stem') {
                // Flow from roots to stem
                const dx = targetX - currentX;
                const dy = targetY - currentY;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance > 1) {
                    particle.style.left = `${currentX + (dx / distance) * speed}px`;
                    particle.style.top = `${currentY + (dy / distance) * speed}px`;

                    // Pulse effect
                    particle.style.opacity = `${0.3 + Math.sin(Date.now() * 0.005) * 0.4}`;
                } else {
                    // Reached target, recycle or change type
                    particle.dataset.type = 'stem-processing';
                    particle.style.background = getParticleColor('processing');
                }
            } else if (type === 'stem-to-branch') {
                // Flow from stem to branches
                const dx = targetX - currentX;
                const dy = targetY - currentY;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance > 1) {
                    particle.style.left = `${currentX + (dx / distance) * speed}px`;
                    particle.style.top = `${currentY + (dy / distance) * speed}px`;

                    // Different pulse for branch flow
                    particle.style.opacity = `${0.4 + Math.sin(Date.now() * 0.007) * 0.3}`;
                } else {
                    particle.dataset.type = 'branch-processing';
                    particle.style.background = getParticleColor('processing');
                }
            } else if (type === 'branch-to-leaf') {
                // Flow from branch to leaves
                const dx = targetX - currentX;
                const dy = targetY - currentY;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance > 1) {
                    particle.style.left = `${currentX + (dx / distance) * speed}px`;
                    particle.style.top = `${currentY + (dy / distance) * speed}px`;

                    // Leaf-specific flow
                    particle.style.opacity = `${0.5 + Math.sin(Date.now() * 0.004) * 0.3}`;
                } else {
                    particle.dataset.type = 'leaf-processing';
                    particle.style.background = getParticleColor('processing');
                }
            } else if (type === 'leaf-to-flower') {
                // Flow from leaves to flower (ML training data)
                const dx = targetX - currentX;
                const dy = targetY - currentY;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance > 1) {
                    particle.style.left = `${currentX + (dx / distance) * speed}px`;
                    particle.style.top = `${currentY + (dy / distance) * speed}px`;

                    // Intensive processing pulse
                    particle.style.opacity = `${0.6 + Math.sin(Date.now() * 0.008) * 0.3}`;
                } else {
                    particle.dataset.type = 'flower-processing';
                    particle.style.background = getParticleColor('intelligence');
                }
            } else if (type === 'energy-pulse') {
                // Energy pulses (for cloud, kubernetes, etc.)
                const pulseSize = 2 + Math.sin(Date.now() * 0.01) * 3;
                particle.style.width = `${pulseSize}px`;
                particle.style.height = `${pulseSize}px`;

                // Radial outward movement
                const angle = Math.atan2(currentY - homeY, currentX - homeX);
                const distanceFromHome = Math.sqrt(
                    Math.pow(currentX - homeX, 2) +
                    Math.pow(currentY - homeY, 2)
                );

                if (distanceFromHome < 80) {
                    particle.style.left = `${currentX + Math.cos(angle) * speed}px`;
                    particle.style.top = `${currentY + Math.sin(angle) * speed}px`;
                } else {
                    // Reset particle
                    particle.style.left = `${homeX}px`;
                    particle.style.top = `${homeY}px`;
                }
            }
        });

        requestAnimationFrame(animateDataParticles);
    }

    // Start the animation loop
    animateDataParticles();

    // Functions to create specific data flows for different stages
    window.dataFlow = {
        createSoilDataParticles,
        createDataParticle,
        animateDataParticles,

        // Specific data flow triggers for different stages
        triggerRootToStemFlow: () => {
            // Create particles flowing from roots to stem
            const rootCount = 5;
            for (let i = 0; i < rootCount; i++) {
                const angle = (i / rootCount) * Math.PI * 2;
                const radius = 20 + Math.random() * 10;
                const startX = 400 + Math.cos(angle) * radius; // Container center
                const startY = 300 + Math.sin(angle) * radius;

                createDataParticle({
                    x: startX,
                    y: startY,
                    type: 'root-to-stem',
                    targetX: 400, // Stem center
                    targetY: 200, // Stem middle of 50
                    speed: 0.8 + Math.random() * 0.4
                });
            }
        },

        triggerStemToBranchFlow: () => {
            // Create particles flowing from stem to branches
            const branchCount = 8;
            for (let i = 0; i < branchCount; i++) {
                const progress = i / branchCount;
                const startX = 400;
                const startY = 100 + (progress * 80); // Along stem

                // Left branch flow
                createDataParticle({
                    x: startX,
                    y: startY,
                    type: 'stem-to-branch',
                    targetX: 320, // Left branch
                    targetY: 80 + (progress * 60),
                    speed: 0.6 + Math.random() * 0.3
                });

                // Right branch flow
                createDataParticle({
                    x: startX,
                    y: startY,
                    type: 'stem-to-branch',
                    targetX: 480, // Right branch
                    targetY: 80 + (progress * 60),
                    speed: 0.6 + Math.random() * 0.3
                });
            }
        },

        triggerLeafToFlowerFlow: () => {
            // Create particles flowing from leaves to flower (ML training)
            const leafCount = 6;
            for (let i = 0; i < leafCount; i++) {
                const progress = i / leafCount;
                const startX = 350 + (progress * 100); // Distribute across leaves
                const startY = 180 + (Math.sin(progress * Math.PI) * 30);

                createDataParticle({
                    x: startX,
                    y: startY,
                    type: 'leaf-to-flower',
                    targetX: 400, // Flower center
                    targetY: 120,
                    speed: 0.5 + Math.random() * 0.3
                });
            }
        },

        triggerEnergyPulse: (centerX, centerY, count = 12) => {
            // Create energy pulses for cloud/kubernetes effects
            for (let i = 0; i < count; i++) {
