        // Create a curved path
        let pathData = `M ${start.x},${start.y}`;

        // Calculate control points for a smooth curve
        const ctrl1x = start.x + (dx * 0.3);
        const ctrl1y = start.y + (dy * 0.3) - (controlOffset * (dx > 0 ? -1 : 1));
        const ctrl2x = start.x + (dx * 0.7);
        const ctrl2y = start.y + (dy * 0.7) + (controlOffset * (dx > 0 ? -1 : 1));

        pathData += `C ${ctrl1x},${ctrl1y} ${ctrl2x},${ctrl2y} ${end.x},${end.y}`;

        connector.element.setAttribute('d', pathData);
    }

    // Animate connector drawing
    function animateConnector(connector, duration = 1.5) {
        const path = connector.element;
        const pathLength = path.getTotalLength();

        // Reset dash array
        path.style.strokeDasharray = `${pathLength} ${pathLength}`;
        path.style.strokeDashoffset = pathLength;
        path.style.opacity = '1';

        // Animate the dash offset
        gsap.to(path, {
            strokeDashoffset: 0,
            duration: duration,
            ease: "power2.out",
            onUpdate: () => {
                // Update path in case elements moved
                updateConnectorPath(connector);
            }
        });

        // Optional: add a pulsing effect
        gsap.fromTo(path,
            { opacity: 0.3 },
            {
                opacity: 0.8,
                duration: duration * 0.5,
                yoyo: true,
                repeat: 1,
                ease: "sine.inOut"
            }
        );
    }

    // Create connector from plant element to info panel
    function createInfoConnector(elementId, side, connectorId) {
        const element = document.getElementById(elementId);
        if (!element) return null;

        // Get element position
        const elementRect = element.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();

        const elementX = elementRect.left + elementRect.width / 2 - containerRect.left;
        const elementY = elementRect.top + elementRect.height / 2 - containerRect.top;

        // Get info panel position
        const infoPanel = side === 'left' ? infoLeft : infoRight;
        const infoRect = infoPanel.getBoundingClientRect();

        let infoX, infoY;
        if (side === 'left') {
            infoX = infoRect.right + 10; // Point to left of info panel
            infoY = infoRect.top + infoRect.height / 2 - containerRect.top;
        } else {
            infoX = infoRect.left - 10; // Point to right of info panel
            infoY = infoRect.top + infoRect.height / 2 - containerRect.top;
        }

        // Create connector
        const connector = createConnector(elementX, elementY, infoX, infoY);
        connector.element.setAttribute('id', `connector-${connectorId}`);

        // Style based on side
        if (side === 'left') {
            connector.element.setAttribute('stroke', '#4fc3f7'); // Blue for left
        } else {
            connector.element.setAttribute('stroke', '#ff9800'); // Orange for right
        }

        return connector;
    }

    // Destroy a connector
    function destroyConnector(connector) {
        const index = activeConnectors.indexOf(connector);
        if (index > -1) {
            activeConnectors.splice(index, 1);
            connector.element.remove();
        }
    }

    // Update all connector positions (call on resize or element movement)
    function updateAllConnectors() {
        activeConnectors.forEach(updateConnectorPath);
    }

    // Expose functions
    window.createInfoConnector = createInfoConnector;
    window.animateConnector = animateConnector;
    window.destroyConnector = destroyConnector;
    window.updateAllConnectors = updateAllConnectors;

    return { createInfoConnector, animateConnector, destroyConnector, updateAllConnectors };
}

