// Scroll.js - Handles ScrollTrigger integration with GSAP timeline

export function initScroll() {
    // Get the master timeline from growth.js
    const masterTimeline = window.masterTimeline;

    if (!masterTimeline) {
        console.error('Master timeline not found. Make sure growth.js is loaded first.');
        return;
    }

    // Configure ScrollTrigger to control the master timeline
    ScrollTrigger.create({
        trigger: "body",
        start: "top top",
        end: "bottom bottom",
        scrub: true, // Smooth scrolling
        animation: masterTimeline,
        // Optional: add markers for debugging
        // markers: true,
        onUpdate: (self) => {
            // Update any dynamic elements based on scroll progress
            const progress = self.progress;

            // Example: update URL or header based on progress
            // document.title = `Technology Growth - ${Math.round(progress * 100)}%`;

            // Update viewport tracking if needed
            updateViewportTracking(progress);
        }
    });

    // Function to update viewport tracking (camera movement)
    function updateViewportTracking(progress) {
        // This would normally adjust the viewBox or transform
        // of a container to follow the growth point
        // For now, we'll keep it simple and let the natural flow handle it

        // Example implementation (commented out for now):
        /*
        const container = document.getElementById('plant-container');
        const growthPoint = getCurrentGrowthPoint(progress);

        if (growthPoint) {
            // Smoothly move container to follow growth point
            gsap.to(container, {
                x: -growthPoint.x + window.innerWidth / 2,
                y: -growthPoint.y + window.innerHeight / 2,
                duration: 0.5,
                ease: "power2.out"
            });
        }
        */
    }

    // Function to get current growth point based on progress
    function getCurrentGrowthPoint(progress) {
        // Map progress to different growth stages
        // This would return the current focal point based on animation progress
        const stages = [
            { start: 0.0, end: 0.05, point: { x: 400, y: 400 } }, // Soil
            { start: 0.05, end: 0.15, point: { x: 400, y: 350 } }, // Seed fall
            { start: 0.15, end: 0.25, point: { x: 400, y: 300 } }, // Germination
            { start: 0.25, end: 0.45, point: { x: 400, y: 250 } }, // Root growth
            { start: 0.45, end: 0.55, point: { x: 400, y: 180 } }, // Stem emergence
            { start: 0.55, end: 0.65, point: { x: 400, y: 120 } }, // Branch development
            { start: 0.65, end: 0.75, point: { x: 400, y: 80 } }, // Leaf growth
            { start: 0.75, end: 0.85, point: { x: 400, y: 60 } }, // Flower blooming
            { start: 0.85, end: 0.95, point: { x: 400, y: 40 } }, // Fruit development
            { start: 0.95, end: 1.0, point: { x: 400, y: 20 } }  // Full tree
        ];

        const stage = stages.find(s => progress >= s.start && progress <= s.end);
        if (stage) {
            // Interpolate within stage
            const stageProgress = (progress - stage.start) / (stage.end - start);
            return {
                x: stage.point.x,
                y: stage.point.y
            };
        }

        return stages[stages.length - 1].point; // Default to end
    }

    // Handle window resize to update scroll triggers
    window.addEventListener('resize', () => {
        ScrollTrigger.refresh();
    });

    // Expose functions
    return {
        updateViewportTracking,
        getCurrentGrowthPoint
    };
}

