// Particles.js - Handles additional particle effects (pollen, data motes, etc.)

export function initParticles() {
    const container = document.getElementById('plant-container');
    const particlesContainer = document.getElementById('particles-container') ||
                            (() => {
                                const div = document.createElement('div');
                                div.id = 'particles-container';
                                div.style.position = 'absolute';
                                div.style.top = '0';
                                div.style.left = '0';
                                div.style.width = '100%';
                                div.style.height = '100%';
                                div.style.pointerEvents = 'none';
                                container.appendChild(div);
                                return div;
                            })();

    // Particle arrays
    let pollenParticles = [];
    let dataMotes = [];
    let backgroundParticles = [];

    // Initialize particle systems
    function initPollenSystem(count = 20) {
        for (let i = 0; i < count; i++) {
            createPollenParticle();
        }
    }

    function initDataMotes(count = 15) {
        for (let i = 0; i < count; i++) {
            createDataMote();
        }
    }

    function initBackgroundParticles(count = 30) {
        for (let i = 0; i < count; i++) {
            createBackgroundParticle();
        }
    }

    // Create pollen particle (for flower blooming effect)
    function createPollenParticle() {
        const particle = document.createElement('div');
        particle.className = 'pollen-particle';
        particle.style.position = 'absolute';
        particle.style.width = `${Math.random() * 2 + 1}px`;
        particle.style.height = particle.style.width;
        particle.style.background = '#ffeb3b'; // Yellow pollen
        particle.style.borderRadius = '50%';
        particle.style.pointerEvents = 'none';
        particle.style.opacity = '0.7';
        particle.style.zIndex = '16';

        // Random initial position (will be updated when flowers bloom)
        particle.style.left = `${Math.random() * 100}%`;
        particle.style.top = `${Math.random() * 100}%`;

        // Store motion data
        particle.dataset.vx = (Math.random() - 0.5) * 0.5;
        particle.dataset.vy = (Math.random() - 0.5) * 0.5;
        particle.dataset.life = Math.random() * 60 + 30; // seconds
        particle.dataset.age = 0;
        particle.dataset.originX = parseFloat(particle.style.left);
        particle.dataset.originY = parseFloat(particle.style.top);

        particlesContainer.appendChild(particle);
        pollenParticles.push(particle);
        return particle;
    }

    // Create data mote (ambient data particles)
    function createDataMote() {
        const particle = document.createElement('div');
        particle.className = 'data-mote';
        particle.style.position = 'absolute';
        particle.style.width = '1px';
        particle.style.height = '1px';
        particle.style.background = '#4fc3f7';
        particle.style.borderRadius = '50%';
        particle.style.pointerEvents = 'none';
        particle.style.opacity = '0.4';
        particle.style.zIndex = '14';

        // Random position
        particle.style.left = `${Math.random() * 100}%`;
        particle.style.top = `${Math.random() * 100}%`;

        // Store motion data
        particle.dataset.vx = (Math.random() - 0.5) * 0.3;
        particle.dataset.vy = (Math.random() - 0.5) * 0.3;
        particle.dataset.speed = Math.random() * 0.5 + 0.2;

        particlesContainer.appendChild(particle);
        dataMotes.push(particle);
        return particle;
    }

    // Create background particle (motes in the "air")
    function createBackgroundParticle() {
        const particle = document.createElement('div');
        particle.className = 'background-particle';
        particle.style.position = 'absolute';
        particle.style.width = `${Math.random() * 1.5 + 0.5}px`;
        particle.style.height = particle.style.width;
        particle.style.background = '#ffffff';
        particle.style.borderRadius = '50%';
        particle.style.pointerEvents = 'none';
        particle.style.opacity = '0.1';
        particle.style.zIndex = '12';

        // Random position
        particle.style.left = `${Math.random() * 100}%`;
        particle.style.top = `${Math.random() * 100}%`;

        // Store motion data
        particle.dataset.vx = (Math.random() - 0.5) * 0.2;
        particle.dataset.vy = (Math.random() - 0.5) * 0.2;
        particle.dataset.driftX = Math.sin(Math.random() * Math.PI * 2) * 0.1;
        particle.dataset.driftY = Math.cos(Math.random() * Math.PI * 2) * 0.1;

        particlesContainer.appendChild(particle);
        backgroundParticles.push(particle);
        return particle;
    }

    // Update all particles
    function updateParticles(deltaTime) {
        // Update pollen particles
        pollenParticles.forEach((particle, index) => {
            let age = parseFloat(particle.dataset.age) + deltaTime;
            const life = parseFloat(particle.dataset.life);

            if (age >= life) {
                // Reset particle
                particle.dataset.age = '0';
                const originX = parseFloat(particle.dataset.originX);
                const originY = parseFloat(particle.dataset.originY);
                particle.style.left = `${originX}%`;
                particle.style.top = `${originY}%`;
                particle.dataset.vx = (Math.random() - 0.5) * 0.5;
                particle.dataset.vy = (Math.random() - 0.5) * 0.5;
            } else {
                particle.dataset.age = age.toString();

                // Apply velocity
                let left = parseFloat(particle.style.left);
                let top = parseFloat(particle.style.top);
                const vx = parseFloat(particle.dataset.vx);
                const vy = parseFloat(particle.dataset.vy);

                left += vx * deltaTime * 16; // Approximate 60fps conversion
                top += vy * deltaTime * 16;

                // Gentle drift toward center
                const centerX = 50;
                const centerY = 50;
                const dx = (centerX - left) * 0.001;
                const dy = (centerY - top) * 0.001;

                particle.dataset.vx = (vx + dx * 0.1).toString();
                particle.dataset.vy = (vy + dy * 0.1).toString();

                // Bound to reasonable area
                left = Math.max(20, Math.min(80, left));
                top = Math.max(20, Math.min(80, top));

                particle.style.left = `${left}%`;
                particle.style.top = `${top}%`;

                // Pulse opacity
                const pulse = Math.sin(age * 0.3) * 0.2 + 0.6;
                particle.style.opacity = pulse.toString();
            }
        });

        // Update data motes
        dataMotes.forEach(particle => {
            let left = parseFloat(particle.style.left);
            let top = parseFloat(particle.style.top);
            const vx = parseFloat(particle.dataset.vx);
            const vy = parseFloat(particle.dataset.vy);

            left += vx * 0.1;
            top += vy * 0.1;

            // Bounce off edges
            if (left <= 0 || left >= 100) {
                particle.dataset.vx = (-vx).toString();
            }
            if (top <= 0 || top >= 100) {
                particle.dataset.vy = (-vy).toString();
            }

            particle.style.left = `${left}%`;
            particle.style.top = `${top}%`;

            // Pulse brightness
            const pulse = Math.sin(Date.now() * 0.002 + parseFloat(particle.dataset.top)) * 0.3 + 0.7;
            particle.style.opacity = `${0.2 + Math.random() * 0.3}`;
        });

        // Update background particles
        backgroundParticles.forEach(particle => {
            let left = parseFloat(particle.style.left);
            let top = parseFloat(particle.style.top);
            const vx = parseFloat(particle.dataset.vx);
            const vy = parseFloat(particle.dataset.vy);
            const driftX = parseFloat(particle.dataset.driftX);
            const driftY = parseFloat(particle.dataset.driftY);

            // Apply base velocity plus drift
            left += vx * 0.05 + driftX * Math.sin(Date.now() * 0.0005);
            top += vy * 0.05 + driftY * Math.cos(Date.now() * 0.0005);

            // Wrap around edges
            if (left < -5) left = 105;
            if (left > 105) left = -5;
            if (top < -5) top = 105;
            if (top > 105) top = -5;

            particle.style.left = `${left}%`;
            particle.style.top = `${top}%`;

            // Slow fade pulse
            const alpha = (Math.sin(Date.now() * 0.001) * 0.05 + 0.1).toString();
            particle.style.opacity = alpha;
        });
    }

    // Animation loop
    let lastTime = 0;
    function animateParticles(timestamp) {
        if (!lastTime) lastTime = timestamp;
        const deltaTime = (timestamp - lastTime) / 16.67; // Normalize to 60fps
        lastTime = timestamp;

        updateParticles(deltaTime);
        requestAnimationFrame(animateParticles);
    }

    // Start particle systems
    initPollenSystem(15);
    initDataMotes(20);
    initBackgroundParticles(40);
    requestAnimationFrame(animateParticles);

    // Special particle bursts for events
    window.particleEffects = {
        createPollenBurst: (x, y, count = 10) => {
            for (let i = 0; i < count; i++) {
                const particle = createPollenParticle();
                particle.style.left = `${x}px`;
                particle.style.top = `${y}px`;
                particle.dataset.originX = ((x / window.innerWidth) * 100).toString();
                particle.dataset.originY = ((y / window.innerHeight) * 100).toString();

                // Outward velocity
                const angle = (i / count) * Math.PI * 2;
                const speed = Math.random() * 2 + 1;
                particle.dataset.vx = (Math.cos(angle) * speed / 10).toString(); // Convert to %/frame
                particle.dataset.vy = (Math.sin(angle) * speed / 10).toString();
                particle.dataset.life = (Math.random() * 30 + 15).toString(); // Shorter life for bursts
            }
        },

        createDataBurst: (x, y, count = 8, type = 'data') => {
            for (let i = 0; i < count; i++) {
                const particle = document.createElement('div');
                particle.className = 'data-burst-particle';
                particle.style.position = 'absolute';
                particle.style.width = '2px';
                particle.style.height = '2px';
                particle.style.background = getParticleColor(type);
                particle.style.borderRadius = '50%';
                particle.style.pointerEvents = 'none';
                particle.style.zIndex = '17';

                particle.style.left = `${x}px`;
                particle.style.top = `${y}px`;

                // Outward velocity with fade
                const angle = (i / count) * Math.PI * 2;
                const speed = Math.random() * 3 + 2;
                particle.dataset.vx = Math.cos(angle) * speed;
                particle.dataset.vy = Math.sin(angle) * speed;
                particle.dataset.life = 20; // frames
                particle.dataset.age = 0;

                particlesContainer.appendChild(particle);

                // Animate and remove
                gsap.to(particle, {
                    x: parseFloat(particle.style.left) + particle.dataset.vx * 20,
                    y: parseFloat(particle.style.top) + particle.dataset.vy * 20,
                    opacity: 0,
                    scale: 0,
                    duration: 0.8,
                    ease: "power2.out",
                    onComplete: () => particle.remove()
                });
            }
        }
    };

    // Helper function to get particle colors
    function getParticleColor(type) {
        const colors = {
            data: '#4fc3f7',
            processing: '#ff8a65',
            intelligence: '#ba68c8',
            energy: '#e57373',
            success: '#81c784',
            warning: '#ffb74d',
            error: '#e57373'
        };
        return colors[type] || '#ffffff';
    }

    // Expose functions
    return {
        createPollenParticle,
        createDataMote,
        createBackgroundParticle,
        updateParticles,
        particleEffects
    };
}

