// Plant.js - Handles creation and basic structure of plant elements

export function initPlant() {
    const container = document.getElementById('plant-container');

    // Create soil
    const soil = document.createElement('div');
    soil.className = 'soil';
    soil.id = 'soil';
    container.appendChild(soil);

    // Create seed
    const seed = document.createElement('div');
    seed.className = 'seed';
    seed.id = 'seed';
    container.appendChild(seed);

    // Create seed label
    const seedLabel = document.createElement('div');
    seedLabel.className = 'seed-label';
    seedLabel.id = 'seed-label';
    seedLabel.textContent = 'DATA';
    seed.appendChild(seedLabel);

    // Create root system container
    const rootsContainer = document.createElement('div');
    rootsContainer.id = 'roots-container';
    container.appendChild(rootsContainer);

    // Create stem
    const stem = document.createElement('div');
    stem.className = 'stem';
    stem.id = 'stem';
    container.appendChild(stem);

    // Create branches container
    const branchesContainer = document.createElement('div');
    branchesContainer.id = 'branches-container';
    container.appendChild(branchesContainer);

    // Create leaves container
    const leavesContainer = document.createElement('div');
    leavesContainer.id = 'leaves-container';
    container.appendChild(leavesContainer);

    // Create flower container
    const flowerContainer = document.createElement('div');
    flowerContainer.id = 'flower-container';
    container.appendChild(flowerContainer);

    // Create fruit container
    const fruitContainer = document.createElement('div');
    fruitContainer.id = 'fruit-container';
    container.appendChild(fruitContainer);

    // Create data particles container
    const particlesContainer = document.createElement('div');
    particlesContainer.id = 'particles-container';
    container.appendChild(particlesContainer);

    // Create connectors container
