    const masterTimeline = gsap.timeline({
        paused: true
    });

    // Label: soil.raw
    masterTimeline.addLabel("soil.raw");

    // Soil animation - subtle movement
    masterTimeline.to(soil, {
        backgroundPosition: "0px 10px",
        duration: 2,
        ease: "sine.inOut",
