// Main JavaScript file - Initializes the application

import { initPlant } from './plant.js';
import { initGrowth } from './growth.js';
import { initDataFlow } from './data-flow.js';
import { initInformation } from './information.js';
import { initConnectors } from './connectors.js';
import { initScroll } from './scroll.js';
import { initParticles } from './particles.js';

// Wait for DOM to load
document.addEventListener('DOMContentLoaded', () => {
    // Initialize all modules
    const plantElements = initPlant();
    const masterTimeline = initGrowth();
    const dataFlow = initDataFlow();
    const information = initInformation();
    const connectors = initConnectors();
    const scroll = initScroll();
    const particles = initParticles();

    // Store references globally for debugging
    window.plantApp = {
        plantElements,
        masterTimeline,
        dataFlow,
        information,
        connectors,
        scroll,
        particles,
        init: () => {
            // Re-initialization function if needed
            console.log('Plant app initialized');
        }
    };

